    public function parse_swyftx_csv_trade(array $trade, ?array $market = null): array {
        // Parse Swyftx CSV format for both trades and deposits/withdrawals
        $dateStr = $this->safe_string($trade, 'Date');
        $timeStr = $this->safe_string($trade, 'Time');
        $event = $this->safe_string($trade, 'Event');
        $asset = $this->safe_string($trade, 'Asset');
        $amount = $this->safe_string($trade, 'Amount');
        $paidCurrency = $this->safe_string($trade, 'Currency');
        $paidValue = $this->safe_string($trade, 'Value');
        $rate = $this->safe_string($trade, 'Rate');
        $uuid = $this->safe_string($trade, 'UUID');
        $txId = $this->safe_string($trade, 'Transaction ID');
        $feeAmount = $this->safe_string($trade, 'Fee Amount');
        $feeAsset = $this->safe_string($trade, 'Fee Asset');
        $section = $this->safe_string($trade, '_section');
        // Parse $datetime from DD/MM/YYYY HH:MM:SS format
        $timestamp = null;
        if ($dateStr && $timeStr) {
            list($day, $month, $year) = explode('/', $dateStr);
            $datetime = `${$year}-$array(str_pad($month, 2, '0', STR_PAD_LEFT))-$array(str_pad($day, 2, '0', STR_PAD_LEFT))T${$timeStr}`;
            $timestamp = $this->parse8601($datetime);
        }
        // Handle different transaction types
        $symbol = null;
        $side = null;
        $type = null;
        $price = null;
        $cost = null;
        if ($section === 'Crypto Transactions') {
            // Crypto trading transactions
            if ($paidCurrency === 'AUD') {
                $symbol = $asset . '/AUD';
            } elseif ($paidCurrency && $paidCurrency !== $asset) {
                $symbol = $asset . '/' . $paidCurrency;
            }
            if ($event === 'buy') {
                $side = 'buy';
            } elseif ($event === 'sell') {
                $side = 'sell';
            }
            $type = 'market';
            $price = $this->parse_number($rate);
            $cost = $this->parse_number($paidValue);
        } elseif ($section === 'Fiat Transactions') {
            // Fiat deposits/withdrawals - represent for consistency
            $symbol = $asset . '/AUD'; // AUD deposits/withdrawals
            if ($event === 'deposit') {
                $side = 'buy';
            } elseif ($event === 'withdrawal') {
                $side = 'sell';
            }
            $type = $event; // 'deposit' or 'withdrawal'
            $price = 1; // 1:1 for fiat
            $cost = $this->parse_number($amount); // Amount is the $cost for fiat
        }
        return $this->safe_trade(array(
            'id' => $uuid || $txId,
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $symbol,
            'order' => null,
            'type' => $type,
            'side' => $side,
            'amount' => $this->parse_number($amount),
            'price' => $price,
            'cost' => $cost,
            'fee' => array(
                'cost' => $this->parse_number($feeAmount),
                'currency' => $feeAsset || $asset,
            ),
        ), $market);
    }

    public function parse_transaction(array $transaction, ?array $currency = null): array {
        // Handle CSV format from $transaction report
        if ($this->safe_string($transaction, '_section')) {
