    public function parse_swyftx_csv_transaction(array $transaction, ?array $currency = null): array {
        // Parse Swyftx CSV format => Date,Time,Event,Asset,Amount,Currency,Value,Rate,AUD Value Fee,AUD Value,Fee Amount,Fee Asset...
        $dateStr = $this->safe_string($transaction, 'Date');
        $timeStr = $this->safe_string($transaction, 'Time');
        $event = $this->safe_string($transaction, 'Event');
        $asset = $this->safe_string($transaction, 'Asset');
        $amount = $this->safe_string($transaction, 'Amount');
        $paidCurrency = $this->safe_string($transaction, 'Currency'); // What was paid (is_array(ETH/BTC trade) && array_key_exists(BTC, ETH/BTC trade))
        $paidValue = $this->safe_string($transaction, 'Value'); // How much was paid
        $txId = $this->safe_string($transaction, 'Transaction ID');
        $uuid = $this->safe_string($transaction, 'UUID');
        $feeAmount = $this->safe_string($transaction, 'Fee Amount');
        $feeAsset = $this->safe_string($transaction, 'Fee Asset');
        // Parse $datetime from DD/MM/YYYY HH:MM:SS format
        $timestamp = null;
        if ($dateStr && $timeStr) {
            list($day, $month, $year) = explode('/', $dateStr);
            $datetime = `${$year}-$array(str_pad($month, 2, '0', STR_PAD_LEFT))-$array(str_pad($day, 2, '0', STR_PAD_LEFT))T${$timeStr}`;
            $timestamp = $this->parse8601($datetime);
        }
        $code = $this->safe_currency_code($asset, $currency);
        // Map Swyftx events to CCXT $transaction types
        $type = $event;
        if ($event === 'buy' || $event === 'sell') {
            $type = 'trade';
        } elseif ($event === 'deposit') {
            $type = 'deposit';
        } elseif ($event === 'withdrawal') {
            $type = 'withdrawal';
        }
        // Add trading pair information for crypto-to-crypto trades
        $comment = null;
        if ($paidCurrency && $paidCurrency !== 'AUD' && $paidCurrency !== $asset) {
            $comment = `${$event} ${$asset} with ${$paidValue} ${$paidCurrency}`;
        }
        return array(
            'info' => $transaction,
            'id' => $uuid || $txId,
            'currency' => $code,
            'amount' => $this->parse_number($amount),
            'network' => null,
            'address' => null,
            'addressTo' => null,
            'addressFrom' => null,
            'tag' => null,
            'tagTo' => null,
            'tagFrom' => null,
            'status' => 'ok', // CSV transactions are typically completed
            'type' => $type,
            'updated' => null,
            'txid' => $txId,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'fee' => array(
                'currency' => $feeAsset || $code,
                'cost' => $this->parse_number($feeAmount),
            ),
            'comment' => $comment,
            'internal' => false,
        );
    }

    public function parse_transaction_status(?string $status): string {
        $statuses = array(
            'completed' => 'ok',
            'pending' => 'pending',
            'failed' => 'failed',
            'cancelled' => 'canceled',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_swyftx_csv_transactions(string $csvText): array {
        $transactions = array();
        $lines = explode('\n', $csvText);
        $currentSection = '';
        $headers = array();
        for ($i = 0; $i < count($lines); $i++) {
            $line = trim($lines[$i]);
            if ($line === 'Crypto Transactions' || $line === 'Fiat Transactions') {
                $currentSection = $line;
                // Next $line should be $headers
                if ($i + 1 < strlen($lines)) {
                    $headers = $lines[$i + explode(',', 1]);
                }
                $i++; // Skip the $header $line
                continue;
            }
            // Skip empty $lines, section $headers, and subtotals
            if (!$line || $line->includes ('sub total') || $line->includes ('Summary') || $line->includes ('no positions')) {
                continue;
            }
            // Parse $transaction data
            if ($currentSection && strlen($headers) > 0 && $line->includes (',')) {
                $values = $this->parse_csv_line($line); // Use proper CSV parsing
                if (strlen($values) >= 3 && $values[0] && $values[1] && $values[2]) { // Must have date, time, and event
                    $transaction = array();
                    for ($j = 0; $j < min (strlen($headers), strlen($values)); $j++) {
                        $header = trim($headers[$j]);
                        $value = trim($values[$j]);
                        if ($header) {
                            $transaction[$header] = $value;
                        }
                    }
                    $transaction['_section'] = $currentSection;
                    $transactions[] = $transaction;
                }
            }
        }
        return $transactions;
    }

    public function parse_csv_line(string $line): array {
        // Simple CSV parser that handles basic comma-separated values
        // This can be improved for more complex CSV with quoted fields if needed
        return explode(',', $line).map ((field) => trim(field));
    }

    public function handle_errors(?int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody): mixed {
        if ($response === null) {
            return null;
        }
        $success = $this->safe_value($response, 'success');
        if ($success === false) {
            $message = $this->safe_string($response, 'message', $body);
            $errorCode = $this->safe_string($response, 'error');
            if ($errorCode === 'UNAUTHORIZED') {
                throw new AuthenticationError($this->id . ' ' . $message);
            }
            throw new ExchangeError($this->id . ' ' . $message);
        }
        return null;
    }
